class RecordingCursor:
    def __init__(
        self,
        *,
        existing_relations: set[str] | None = None,
        filter_rows: list[dict[str, Any]] | None = None,
        columns_by_table: dict[str, list[str]] | None = None,
    ) -> None:
        self.executions: list[tuple[str, Any]] = []
        self.existing_relations = existing_relations or set()
        self.filter_rows = [dict(row) for row in (filter_rows or [])]
        self.columns_by_table_override = columns_by_table
        self._last_sql = ""
        self._last_params: Any = None

    def __enter__(self) -> "RecordingCursor":
        return self

    def __exit__(self, *_: object) -> None:
        return None

    def execute(self, sql: str, params: Any = None) -> None:
        if isinstance(params, dict):
            recorded_params: Any = dict(params)
            none_filter_params = {
                key: value
                for key, value in recorded_params.items()
                if key not in {"user_id", "limit"} and value is None
            }
            if none_filter_params:
                raise AssertionError(f"nullable filter params should be omitted: {sorted(none_filter_params)}")
        elif params is None:
            recorded_params = {}
        else:
            recorded_params = tuple(params)
        self._last_sql = sql
        self._last_params = recorded_params
        self.executions.append((sql, recorded_params))

    def fetchone(self) -> dict[str, Any] | None:
        if "to_regclass" in self._last_sql and isinstance(self._last_params, tuple) and self._last_params:
            relation_name = str(self._last_params[0])
            if relation_name in self.existing_relations:
                return {"relation_name": relation_name}
            return {"relation_name": None}
        if (
            "SELECT source_trade_date::text AS source_trade_date" in self._last_sql
            or "SELECT min(source_trade_date::text) AS source_trade_date" in self._last_sql
        ):
            return {
                "source_trade_date": "20260624",
                "for_trade_date": "20260625",
                "source_run_id": "condition_run_20260624",
            }
        return None

    def fetchall(self) -> list[dict[str, Any]]:
        if "SELECT for_trade_date::text AS for_trade_date" in self._last_sql:
            return [{"for_trade_date": "20260625", "source_run_id": "condition_run_20260625"}]
        if "FROM pg_catalog.pg_class c" in self._last_sql:
            requested = set(self._last_params[0]) if isinstance(self._last_params, tuple) and self._last_params else set()
            default_columns = {
                table_name: [
                    "monitor_id",
                    "principal_id",
                    "principal_type",
                    "user_id",
                    "asset_kind",
                    "identity_key",
                    "direction",
                    "source_type",
                    "source_run_id",
                    "source_snapshot_json",
                    "valid_source_trade_date",
                    "valid_for_trade_date",
                    "valid_source_run_id",
                    "status",
                ]
                for table_name in ("user_monitor_stock", "user_monitor_index", "user_monitor_board")
            }
            default_columns.update(
                {
                    view_name: [
                        "identity_key",
                        "source_trade_date",
                        "for_trade_date",
                        "run_id",
                        "updated_at",
                    ]
                    for view_name in (
                        "v_n6_stock_condition_display_basis",
                        "v_n6_index_condition_display_basis",
                        "v_n6_board_condition_display_basis",
                    )
                }
            )
            default_columns["v_n6_board_membership_fact"] = [
                "trade_date",
                "board_identity_key",
                "stock_identity_key",
                "board_code",
                "board_name",
                "board_type",
            ]
            default_columns[n6_user_app_module.APP_REALTIME_SCOPE_TABLE] = [
                "realtime_scope_id",
                "principal_id",
                "principal_type",
                "user_id",
                "asset_kind",
                "identity_key",
                "status",
            ]
            columns_by_table = self.columns_by_table_override or default_columns
            return [
                {"relation_name": relation_name, "column_name": column_name}
                for relation_name in sorted(self.existing_relations.intersection(requested))
                for column_name in columns_by_table.get(relation_name, ["identity_key"])
            ]
        if "information_schema.columns" in self._last_sql and isinstance(self._last_params, tuple) and self._last_params:
            table_name = str(self._last_params[0])
            columns_by_table = self.columns_by_table_override or {
                "v_n6_stock_condition_display_basis": [
                    "identity_key",
                    "for_trade_date",
                    "source_trade_date",
                    "updated_at",
                    "score",
                    "display_name",
                ],
                "v_n6_index_condition_display_basis": [
                    "identity_key",
                    "for_trade_date",
                    "source_trade_date",
                    "updated_at",
                    "score",
                    "display_name",
                ],
                "v_n6_board_condition_display_basis": [
                    "identity_key",
                    "for_trade_date",
                    "source_trade_date",
                    "updated_at",
                    "score",
                    "display_name",
                ],
                "user_monitor_stock": [
                    "monitor_id",
                    "principal_id",
                    "principal_type",
                    "user_id",
                    "asset_kind",
                    "identity_key",
                    "direction",
                    "source_snapshot_json",
                    "valid_source_trade_date",
                    "valid_for_trade_date",
                    "valid_source_run_id",
                ],
                "user_monitor_index": [
                    "monitor_id",
                    "principal_id",
                    "principal_type",
                    "user_id",
                    "asset_kind",
                    "identity_key",
                    "direction",
                    "source_snapshot_json",
                    "valid_source_trade_date",
                    "valid_for_trade_date",
                    "valid_source_run_id",
                ],
                "user_monitor_board": [
                    "monitor_id",
                    "principal_id",
                    "principal_type",
                    "user_id",
                    "asset_kind",
                    "identity_key",
                    "direction",
                    "source_snapshot_json",
                    "valid_source_trade_date",
                    "valid_for_trade_date",
                    "valid_source_run_id",
                ],
            }
            return [{"column_name": column} for column in columns_by_table.get(table_name, [])]
        if "FROM v_n6_stock_condition_display_basis t" in self._last_sql:
            return [dict(row) for row in self.filter_rows]
        return []


class RecordingConnection:
    def __init__(self, cursor: RecordingCursor) -> None:
        self._cursor = cursor

    def __enter__(self) -> "RecordingConnection":
        return self

    def __exit__(self, *_: object) -> None:
        return None

    def cursor(self) -> RecordingCursor:
        return self._cursor


class N6UserAppTest(unittest.TestCase):
    def test_web_observability_logs_low_cardinality_routes_status_and_elapsed_without_secrets(
        self,
    ) -> None:
        client, repo, _, _ = build_client(raise_server_exceptions=False)

        async def observed_route(opaque: str) -> dict[str, bool]:
            del opaque
            return {"ok": True}

        async def failing_route() -> None:
            raise RuntimeError("fixture failure")

        client.app.add_api_route(
            "/n6/observability/{opaque}",
            observed_route,
            methods=["GET"],
        )
        client.app.add_api_route(
            "/n6/observability-error",
            failing_route,
            methods=["GET"],
        )
        secret_values = (
            "query-secret-91",
            "password-secret-92",
            "cookie-secret-93",
            "authorization-secret-94",
            "session-token-secret-95",
            "postgresql://secret-dsn-96",
            "SELECT-secret-sql-97",
            "principal-user-secret-98",
            "identity-source-projection-secret-99",
        )

        with self.assertLogs(
            n6_user_app_module.N6_WEB_OBSERVABILITY_LOGGER,
            level="INFO",
        ) as captured:
            unauthorized = client.get("/api/n6/me")
            redirect = client.post(
                "/api/n6/auth/login",
                json={
                    "login_name": "admin",
                    "password": secret_values[1],
                },
            )
            observed = client.get(
                f"/n6/observability/{secret_values[0]}",
                params={"password": secret_values[0], "dsn": secret_values[5]},
                headers={
                    "Authorization": f"Bearer {secret_values[3]}",
                    "Cookie": f"unsafe={secret_values[2]}",
                },
            )
            repo.app_principals = []
            forbidden = client.get("/api/n6/app/v1/me")
            missing = client.get("/n6/does-not-exist")
            failed = client.get("/n6/observability-error")

        self.assertEqual(
            [
                unauthorized.status_code,
                redirect.status_code,
                observed.status_code,
                forbidden.status_code,
                missing.status_code,
                failed.status_code,
            ],
            [401, 302, 200, 403, 404, 500],
        )
        events = [
            json.loads(record.getMessage())
            for record in captured.records
            if json.loads(record.getMessage()).get("event") == "n6_http_request"
        ]
        self.assertEqual(
            {event["status"] for event in events},
            {200, 302, 401, 403, 404, 500},
        )
        observed_events = [
            event
            for event in events
            if event["route_family"] == "/n6/observability/{opaque}"
        ]
        self.assertEqual(len(observed_events), 1)
        self.assertEqual(observed_events[0]["method"], "GET")
        self.assertGreaterEqual(observed_events[0]["elapsed_ms"], 0)
        self.assertTrue(
            any(
                event["route_family"] == "/n6/observability-error"
                and event["status"] == 500
                for event in events
            )
        )
        self.assertTrue(
            any(
                event["route_family"] == "unmatched" and event["status"] == 404
                for event in events
            )
        )
        serialized = "\n".join(record.getMessage() for record in captured.records)
        for secret in secret_values:
            self.assertNotIn(secret, serialized)
        for forbidden_field in (
            "query_string",
            "cookie",
            "authorization",
            "token",
            "dsn",
            "sql",
            "principal_id",
            "user_id",
            "identity_key",
            "source_id",
            "projection_id",
            "request_body",
            "response_body",
        ):
            self.assertNotIn(forbidden_field, serialized.lower())

    def test_etag_observability_records_only_cache_family_and_hit_or_miss(self) -> None:
        client, repo, _, _ = build_client()
        seed_effective_monitor_for_signal(repo, repo.ui_v1_signals[0])
        client.post(
            "/api/n6/auth/login",
            json={"login_name": "admin", "password": "correct-password"},
        )

        with self.assertLogs(
            n6_user_app_module.N6_WEB_OBSERVABILITY_LOGGER,
            level="INFO",
        ) as captured:
            initial = client.get("/api/n6/app/v1/signals")
            unchanged = client.get(
                "/api/n6/app/v1/signals",
                headers={"If-None-Match": initial.headers["etag"]},
            )

        self.assertEqual(initial.status_code, 200)
        self.assertEqual(unchanged.status_code, 304)
        cache_events = [
            json.loads(record.getMessage())
            for record in captured.records
            if json.loads(record.getMessage()).get("event") == "n6_cache_lookup"
        ]
        self.assertEqual(
            cache_events,
            [
                {
                    "cache_family": "signal_list",
                    "cache_status": "miss",
                    "event": "n6_cache_lookup",
                },
                {
                    "cache_family": "signal_list",
                    "cache_status": "hit",
                    "event": "n6_cache_lookup",
                },
            ],
        )

    def test_dashboard_uses_one_request_scoped_readonly_repository_context(self) -> None:
        class DashboardRepository(FakeN6UserRepository):
            def __init__(self) -> None:
                super().__init__()
                self.readonly_request_enters = 0
                self.readonly_request_exits = 0

            @contextmanager
            def readonly_request(self) -> Any:
                self.readonly_request_enters += 1
                try:
                    yield
                finally:
                    self.readonly_request_exits += 1

        repo = DashboardRepository()
        seed_effective_monitor_for_signal(repo, repo.ui_v1_signals[0])
        client, _, _, _ = build_client(repository=repo)
        client.post(
            "/api/n6/auth/login",
            json={"login_name": "admin", "password": "correct-password"},
        )

        response = client.get("/api/n6/app/v1/dashboard")

        self.assertEqual(response.status_code, 200)
        self.assertEqual(repo.readonly_request_enters, 1)
        self.assertEqual(repo.readonly_request_exits, 1)
        self.assertEqual(repo.app_signal_reads, [(1, "admin", 1)])
        self.assertEqual(repo.app_virtual_account_reads, [(1, "admin")])
        self.assertFalse(any(repo.forbidden_writes.values()))

    def test_postgres_readonly_request_reuses_and_releases_connection_on_success_and_error(
        self,
    ) -> None:
        cursor = RecordingCursor()
        counts = {"opened": 0, "exited": 0, "error_exits": 0}

        class TrackingConnection(RecordingConnection):
            def __exit__(self, exc_type: object, *_: object) -> None:
                counts["exited"] += 1
                if exc_type is not None:
                    counts["error_exits"] += 1
                return None

        repo = PostgresN6UserRepository("postgresql://unused")

        def readonly_connection(*_: Any, **__: Any) -> RecordingConnection:
            counts["opened"] += 1
            return TrackingConnection(cursor)

        with patch.object(
            n6_user_app_module.psycopg,
            "connect",
            side_effect=readonly_connection,
        ):
            for _ in range(5):
                self.assertIsNone(repo.fetch_top_index_strategy())
                self.assertEqual(repo.fetch_strong_boards(3), [])
            self.assertEqual(counts, {"opened": 10, "exited": 10, "error_exits": 0})

            counts.update(opened=0, exited=0, error_exits=0)
            with repo.readonly_request():
                for _ in range(5):
                    self.assertIsNone(repo.fetch_top_index_strategy())
                    self.assertEqual(repo.fetch_strong_boards(3), [])

            self.assertEqual(counts, {"opened": 1, "exited": 1, "error_exits": 0})

            with self.assertRaisesRegex(RuntimeError, "fixture failure"):
                with repo.readonly_request():
                    raise RuntimeError("fixture failure")

            self.assertEqual(counts, {"opened": 2, "exited": 2, "error_exits": 1})
            self.assertIsNone(repo.fetch_top_index_strategy())
            self.assertEqual(counts, {"opened": 3, "exited": 3, "error_exits": 1})

    def test_proposal_restore_get_requires_actual_page_controls(self) -> None:
        client, _, _, _ = build_client(
            proposal_write_enabled=True,
            csrf_secret="proposal-secret",
        )
        client.post(
            "/api/n6/auth/login",
            json={"login_name": "admin", "password": "correct-password"},
        )
        guide = client.get("/n6/app/guide")
        self.assertEqual(guide.status_code, 200)
        self.assertNotIn(
            "data-n6-create-proposal",
            guide.text.split("<script>", 1)[0],
        )

        source = (TEMPLATE_DIR / "n6_app_shell.html").read_text(encoding="utf-8")
        scope_write_source = source.split("const n6ScopeWrite = (() => {", 1)[1]
        init_source = scope_write_source.split("const init = () => {", 1)[1].split(
            "return { init };",
            1,
        )[0]

        self.assertIn(
            'const proposalButtons = document.querySelectorAll("[data-n6-create-proposal]");',
            init_source,
        )
        self.assertIn(
            "if (proposalWriteEnabled && proposalButtons.length) restoreProposalButtons()",
            init_source,
        )

    def test_login_success_writes_session_hash_and_cookie_raw_token(self) -> None:
        client, repo, verifier, _ = build_client()

        response = client.post(
            "/api/n6/auth/login",
            json={"login_name": "admin", "password": "correct-password"},
            follow_redirects=False,
        )

        self.assertEqual(response.status_code, 302)
        self.assertEqual(response.headers["location"], "/n6/post-close-fastlane-status")
        self.assertEqual(len(repo.created_sessions), 1)
        raw_cookie = response.cookies.get(COOKIE_NAME)
        self.assertIsNotNone(raw_cookie)
        session_row = repo.created_sessions[0]
        self.assertEqual(session_row["session_token_hash_algo"], "sha256")
        self.assertEqual(session_row["session_token_hash"], hash_session_token(str(raw_cookie)))
        self.assertNotEqual(session_row["session_token_hash"], raw_cookie)
        self.assertEqual(verifier.calls, [("correct-password", "stored-password-hash", "argon2id")])
        set_cookie = response.headers["set-cookie"]
        self.assertIn("HttpOnly", set_cookie)
        self.assertIn("SameSite=lax", set_cookie)
        self.assertIn("Path=/", set_cookie)
        self.assertNotIn("Secure", set_cookie)

    def test_https_reverse_proxy_mode_explicitly_enables_secure_cookie(self) -> None:
        client, _, _, _ = build_client(cookie_secure=True)

        response = client.post(
            "/api/n6/auth/login",
            json={"login_name": "admin", "password": "correct-password"},
            follow_redirects=False,
        )

        self.assertEqual(response.status_code, 302)
        self.assertIn("Secure", response.headers["set-cookie"])

    def test_security_headers_are_minimal_and_do_not_break_http_or_inline_assets(self) -> None:
        client, _, _, _ = build_client()

        login_page = client.get("/n6/login")
        unauthorized = client.get("/api/n6/me")

        for response in (login_page, unauthorized):
            self.assertEqual(response.headers["x-content-type-options"], "nosniff")
            self.assertEqual(response.headers["x-frame-options"], "DENY")
            self.assertEqual(response.headers["referrer-policy"], "same-origin")
            self.assertNotIn("strict-transport-security", response.headers)
            self.assertNotIn("content-security-policy", response.headers)

    def test_deployment_env_contract_separates_http_and_https_proxy_modes(self) -> None:
        with patch.dict(os.environ, {}, clear=True):
            local_config = n6_user_app_module.config_from_env()
        with patch.dict(
            os.environ,
            {
                "ASHARE_V3_N6_COOKIE_SECURE": "1",
                "ASHARE_V3_N6_TRUSTED_PROXY_IPS": "127.0.0.1, ::1",
            },
            clear=True,
        ):
            proxy_config = n6_user_app_module.config_from_env()

        self.assertFalse(local_config.cookie_secure)
        self.assertEqual(local_config.trusted_proxy_ips, ())
        self.assertTrue(proxy_config.cookie_secure)
        self.assertEqual(proxy_config.trusted_proxy_ips, ("127.0.0.1", "::1"))

    def test_login_rate_limit_is_generic_normalized_and_success_clears_window(self) -> None:
        verifier = FixedPasswordVerifier(False)
        client, repo, _, _ = build_client(
            verifier=verifier,
            login_rate_limit_attempts=3,
        )

        for login_name in (" Admin ", "ADMIN"):
            response = client.post(
                "/api/n6/auth/login",
                json={"login_name": login_name, "password": "wrong-password"},
            )
            self.assertEqual(response.status_code, 401)
            self.assertEqual(response.json(), {"ok": False, "error": "invalid_login"})

        verifier.result = True
        success = client.post(
            "/api/n6/auth/login",
            json={"login_name": "admin", "password": "correct-password"},
            follow_redirects=False,
        )
        self.assertEqual(success.status_code, 302)
        self.assertEqual(len(repo.created_sessions), 1)

        verifier.result = False
        for _ in range(3):
            self.assertEqual(
                client.post(
                    "/api/n6/auth/login",
                    json={"login_name": "admin", "password": "wrong-password"},
                ).status_code,
                401,
            )
        limited = client.post(
            "/api/n6/auth/login",
            json={"login_name": "admin", "password": "wrong-password"},
        )
        self.assertEqual(limited.status_code, 429)
        self.assertEqual(limited.json(), {"ok": False, "error": "invalid_login"})
        self.assertEqual(limited.headers["retry-after"], "60")
        self.assertEqual(len(repo.created_sessions), 1)

    def test_login_rate_limit_uses_forwarded_client_only_from_exact_trusted_proxy(self) -> None:
        untrusted_client, _, _, _ = build_client(
            verifier=FixedPasswordVerifier(False),
            login_rate_limit_attempts=1,
            client_host="127.0.0.1",
        )
        first = untrusted_client.post(
            "/api/n6/auth/login",
            headers={"X-Forwarded-For": "203.0.113.1"},
            json={"login_name": "missing", "password": "wrong"},
        )
        spoofed = untrusted_client.post(
            "/api/n6/auth/login",
            headers={"X-Forwarded-For": "203.0.113.2"},
            json={"login_name": "missing", "password": "wrong"},
        )

        trusted_client, _, _, _ = build_client(
            verifier=FixedPasswordVerifier(False),
            login_rate_limit_attempts=1,
            client_host="127.0.0.1",
            trusted_proxy_ips=("127.0.0.1",),
        )
        trusted_first = trusted_client.post(
            "/api/n6/auth/login",
            headers={"X-Forwarded-For": "198.51.100.1"},
            json={"login_name": "missing", "password": "wrong"},
        )
        trusted_second = trusted_client.post(
            "/api/n6/auth/login",
            headers={"X-Forwarded-For": "198.51.100.2"},
            json={"login_name": "missing", "password": "wrong"},
        )

        self.assertEqual(first.status_code, 401)
        self.assertEqual(spoofed.status_code, 429)
        self.assertEqual(spoofed.json(), {"ok": False, "error": "invalid_login"})
        self.assertEqual(trusted_first.status_code, 401)
        self.assertEqual(trusted_second.status_code, 401)

    def test_login_failure_does_not_disclose_account_existence(self) -> None:
        verifier = FixedPasswordVerifier(False)
        client, _, _, _ = build_client(verifier=verifier)

        known = client.post(
            "/api/n6/auth/login",
            json={"login_name": "admin", "password": "wrong-password"},
        )
        missing = client.post(
            "/api/n6/auth/login",
            json={"login_name": "missing", "password": "wrong-password"},
        )

        self.assertEqual(
            (known.status_code, known.json()),
            (401, {"ok": False, "error": "invalid_login"}),
        )
        self.assertEqual(
            (missing.status_code, missing.json()),
            (401, {"ok": False, "error": "invalid_login"}),
        )
        self.assertEqual(len(verifier.calls), 2)
        self.assertEqual(verifier.calls[0][2], "argon2id")
        self.assertEqual(verifier.calls[1][2], "argon2id")
        self.assertNotEqual(verifier.calls[1][1], "")

    def test_login_lookup_operational_error_returns_fixed_503_then_recovers(self) -> None:
        client, repo, verifier, _ = build_client(raise_server_exceptions=False)
        detail = "lookup connection detail must not leak"
        with patch.object(
            repo,
            "fetch_user_for_login",
            side_effect=[
                n6_user_app_module.psycopg.OperationalError(detail),
                repo.users_by_login["admin"],
            ],
        ):
            unavailable = client.post(
                "/api/n6/auth/login",
                json={"login_name": "admin", "password": "correct-password"},
                follow_redirects=False,
            )
            recovered = client.post(
                "/api/n6/auth/login",
                json={"login_name": "admin", "password": "correct-password"},
                follow_redirects=False,
            )

        self.assertEqual(unavailable.status_code, 503)
        self.assertEqual(
            unavailable.json(),
            {"ok": False, "error": "authentication_service_unavailable"},
        )
        self.assertEqual(unavailable.headers.get("retry-after"), "5")
        self.assertNotIn("set-cookie", unavailable.headers)
        self.assertNotIn(detail, unavailable.text)
        self.assertEqual(recovered.status_code, 302)
        self.assertEqual(recovered.headers["location"], "/n6/post-close-fastlane-status")
        self.assertIn("set-cookie", recovered.headers)
        self.assertEqual(len(repo.created_sessions), 1)
        self.assertEqual(len(repo.sessions_by_hash), 1)
        self.assertEqual(
            verifier.calls,
            [("correct-password", "stored-password-hash", "argon2id")],
        )

    def test_login_create_session_operational_error_returns_fixed_503(self) -> None:
        client, repo, verifier, _ = build_client(raise_server_exceptions=False)
        detail = "session connection detail must not leak"
        with patch.object(
            repo,
            "create_session",
            side_effect=n6_user_app_module.psycopg.OperationalError(detail),
        ):
            response = client.post(
                "/api/n6/auth/login",
                json={"login_name": "admin", "password": "correct-password"},
                follow_redirects=False,
            )

        self.assertEqual(response.status_code, 503)
        self.assertEqual(
            response.json(),
            {"ok": False, "error": "authentication_service_unavailable"},
        )
        self.assertEqual(response.headers.get("retry-after"), "5")
        self.assertNotIn("set-cookie", response.headers)
        self.assertNotIn(detail, response.text)
        self.assertEqual(repo.created_sessions, [])
        self.assertEqual(repo.sessions_by_hash, {})
        self.assertEqual(
            verifier.calls,
            [("correct-password", "stored-password-hash", "argon2id")],
        )

    def test_login_programming_error_is_not_swallowed_at_repository_boundaries(self) -> None:
        for repository_call in ("fetch_user_for_login", "create_session"):
            with self.subTest(repository_call=repository_call):
                client, repo, _, _ = build_client()
                with patch.object(
                    repo,
                    repository_call,
                    side_effect=n6_user_app_module.psycopg.ProgrammingError(
                        f"{repository_call} programming error"
                    ),
                ):
                    with self.assertRaises(n6_user_app_module.psycopg.ProgrammingError):
                        client.post(
                            "/api/n6/auth/login",
                            json={"login_name": "admin", "password": "correct-password"},
                            follow_redirects=False,
                        )

