class N6SignalSSEContractTest(unittest.TestCase):
    def test_auth_expiry_stops_sse_correction_and_voice_without_retrying(self) -> None:
        source = (TEMPLATE_DIR / "n6_app_shell.html").read_text(encoding="utf-8")
        refresh_source = source.split("const n6AutoRefresh = (() => {", 1)[1].split(
            "const n6ScopeWrite = (() => {", 1
        )[0]
        expire_source = refresh_source.split("const expireSession =", 1)[1].split(
            "const probeAuthAfterSseError =", 1
        )[0]
        refresh_once_source = refresh_source.split("const refreshOnce =", 1)[1].split(
            "const foregroundCurrent =", 1
        )[0]
        sse_probe_source = refresh_source.split("const probeAuthAfterSseError =", 1)[1].split(
            "const rebuildEventSource =", 1
        )[0]

        self.assertIn("clearCorrectionTimer();", expire_source)
        self.assertIn("closeEventSource();", expire_source)
        self.assertIn('root.dataset.refreshEnabled = "false";', expire_source)
        self.assertIn("state.controllers.forEach((controller) => controller.abort());", expire_source)
        self.assertIn("n6Voice.stop();", expire_source)
        self.assertIn('link.textContent = "会话已过期，请重新登录";', refresh_source)
        self.assertIn("response.status === 401 || response.status === 403", refresh_once_source)
        self.assertIn("response.status === 401 || response.status === 403", sse_probe_source)
        self.assertIn("expireSession();", refresh_once_source)
        self.assertIn("expireSession();", sse_probe_source)
        self.assertIn(
            "eventSource.onerror = () => { void probeAuthAfterSseError(root); };",
            refresh_source,
        )
        self.assertIn("if (sessionExpired || !foregroundCurrent(root)", refresh_source)
        self.assertEqual(refresh_source.count("new EventSource("), 1)

    def test_sse_message_voice_only_runs_for_new_insertions_without_recovery_or_history_drift(
        self,
    ) -> None:
        source = (TEMPLATE_DIR / "n6_app_shell.html").read_text(encoding="utf-8")
        refresh_source = source.split("const n6AutoRefresh = (() => {", 1)[1].split(
            "const n6ScopeWrite = (() => {", 1
        )[0]
        sse_apply_source = refresh_source.split("const applySignalEvent =", 1)[1].split(
            "const refreshOnce =", 1
        )[0]
        inserted_branch = (
            "updateLoadedMessageSummary();\n"
            "        if (inserted) n6Voice.speak(cardItem);\n"
            "        applyMobileCardWindow(root);\n"
            "        return inserted ? 1 : 0;"
        )

        self.assertIn(inserted_branch, sse_apply_source)
        self.assertEqual(sse_apply_source.count("n6Voice.speak(cardItem)"), 1)
        before_inserted, after_inserted = sse_apply_source.split(
            "if (inserted) n6Voice.speak(cardItem);", 1
        )
        self.assertNotIn("n6Voice.speak", before_inserted)
        self.assertNotIn("n6Voice.speak", after_inserted)

        recover_source = refresh_source.split("const recoverLive =", 1)[1].split(
            "const init =", 1
        )[0]
        self.assertIn("await withVoiceSuppressed(() => refreshOnce(", recover_source)
        self.assertIn(
            "{ append: false, silent: true, speakNew: false }",
            recover_source,
        )
        init_source = refresh_source.split("const init =", 1)[1]
        self.assertIn(
            "{ append: false, silent: false, speakNew: false }",
            init_source,
        )
        self.assertIn('if (root.dataset.refreshEnabled !== "true") return;', init_source)
        self.assertEqual(refresh_source.count("new EventSource("), 1)

    def test_bigint_dto_normalizer_is_exact_and_field_allowlisted(self) -> None:
        normalize = n6_app_v1_module.canonical_bigint_id

        self.assertEqual(
            normalize("9007199254740993", field_name="user_signal_projection_id", required=True),
            "9007199254740993",
        )
        self.assertEqual(
            normalize(2**63 - 1, field_name="user_signal_card_id", required=True),
            str(2**63 - 1),
        )
        self.assertEqual(
            normalize(2**63 - 1, field_name="principal_id", required=True),
            str(2**63 - 1),
        )
        self.assertIsNone(normalize(None, field_name="source_condition_display_basis_id"))
        for value in (True, 1.0, "1.5", "01", "-1", 0, 2**63):
            with self.subTest(value=value), self.assertRaises(ValueError):
                normalize(value, field_name="user_signal_projection_id", required=True)
            with self.subTest(principal_value=value), self.assertRaises(ValueError):
                normalize(value, field_name="principal_id", required=True)
        with self.assertRaises(ValueError):
            normalize(1, field_name="current_price", required=True)

    def test_filter_and_monitor_bigint_dtos_are_canonical_and_nullable(self) -> None:
        maximum_id = 2**63 - 1

        small_filter = n6_app_v1_module._app_v2_filter_item(
            {"source_display_basis_id": 7, "identity_key": "stock:SH:600000"},
            asset_kind="stock",
            include_linked_stock_actions=False,
        )
        maximum_filter = n6_app_v1_module._app_v2_filter_item(
            {"source_display_basis_id": maximum_id, "identity_key": "stock:SH:600000"},
            asset_kind="stock",
            include_linked_stock_actions=False,
        )
        nullable_filter = n6_app_v1_module._app_v2_filter_item(
            {"identity_key": "stock:SH:600000"},
            asset_kind="stock",
            include_linked_stock_actions=False,
        )
        small_monitor = n6_app_v1_module.app_v2_monitor_item(
            {
                "monitor_id": 11,
                "principal_id": 1,
                "asset_kind": "stock",
                "identity_key": "stock:SH:600000",
            }
        )
        maximum_monitor = n6_app_v1_module.app_v2_monitor_item(
            {
                "monitor_id": maximum_id,
                "principal_id": maximum_id,
                "asset_kind": "stock",
                "identity_key": "stock:SH:600000",
            }
        )

        self.assertEqual(small_filter["source_display_basis_id"], "7")
        self.assertEqual(maximum_filter["source_display_basis_id"], str(maximum_id))
        self.assertIsNone(nullable_filter["source_display_basis_id"])
        self.assertEqual(small_monitor["monitor_id"], "11")
        self.assertEqual(small_monitor["principal_id"], "1")
        self.assertEqual(maximum_monitor["monitor_id"], str(maximum_id))
        self.assertEqual(maximum_monitor["principal_id"], str(maximum_id))
        self.assertNotIn("source_display_basis_id_numeric", maximum_filter)
        self.assertNotIn("monitor_id_numeric", maximum_monitor)
        self.assertNotIn("principal_id_numeric", maximum_monitor)

